contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test entry. We take an address for LogFile and a value for MinSum.
    function run(address logAddr, uint minVal) public payable {
        // No precondition on c's state; operate on freshly deployed c by checker.

        // First, attempt to call SetMinSum and SetLogFile BEFORE initialization and record whether they revert.
        bool setMinBeforeReverted;
        c.SetMinSum(minVal); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setMinBeforeReverted = true;
        } else {
            setMinBeforeReverted = false;
        }

        bool setLogBeforeReverted;
        c.SetLogFile(logAddr); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setLogBeforeReverted = true;
        } else {
            setLogBeforeReverted = false;
        }

        // Now call Initialized() (it may revert if already initialized; record whether it reverts)
        bool initReverted;
        c.Initialized(); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            initReverted = true;
        } else {
            initReverted = false;
        }

        // After calling Initialized (regardless of whether the call itself reverted), attempt SetMinSum and SetLogFile again and see if they revert.
        bool setMinAfterReverted;
        c.SetMinSum(minVal); bool __rev3 = __ESBMC_reverted(); if (__rev3) {
            setMinAfterReverted = true;
        } else {
            setMinAfterReverted = false;
        }

        bool setLogAfterReverted;
        c.SetLogFile(logAddr); bool __rev4 = __ESBMC_reverted(); if (__rev4) {
            setLogAfterReverted = true;
        } else {
            setLogAfterReverted = false;
        }

        // General rule asserted:
        // If Initialized() succeeded (initReverted == false) then subsequent SetMinSum and SetLogFile MUST revert (be true).
        // If Initialized() reverted (initReverted == true), we cannot require behavior after; however, it's allowed that before-initialization calls either reverted or not.
        // Thus assert: init succeeded => both after calls reverted.
        assert(initReverted || (setMinAfterReverted && setLogAfterReverted));
    }

    receive() external payable {}
}

